actor BoundedQueue {
  private var buffer: [Job] = []; private var waiters: [CheckedContinuation<Job, Never>] = []
  private let capacity = 1000
  func push(_ job: Job) {
    if let w = waiters.first { waiters.removeFirst(); w.resume(returning: job) }
    else { precondition(buffer.count < capacity); buffer.append(job) }
  }
  func pop() async -> Job {
    if !buffer.isEmpty { return buffer.removeFirst() }
    return await withCheckedContinuation { waiters.append($0) }   // suspends while empty
  }
}

